      'enhance.status.clientUpdated': { 'zh-CN': '配置已保存 · 客户端更新待重写入', 'zh-TW': '設定已儲存 · 用戶端更新待重寫入', en: 'Saved · Client Updated (Reapply)' },
      'enhance.status.diskMismatch': { 'zh-CN': '配置已保存 · 磁盘待写入', 'zh-TW': '設定已儲存 · 磁碟待寫入', en: 'Saved · Disk Out of Sync' },
